## 1️⃣ Market Data Feed Subsystem

### 1.1 Core Types

```csharp
// src/MarketData/PriceTick.cs
namespace MarketData;

public sealed record PriceTick
{
    public string Symbol { get; init; }          // e.g. "AAPL"
    public decimal Price { get; init; }          // last traded price
    public DateTime TimestampUtc { get; init; } // UTC time of the tick
}
```

### 1.2 Provider Interface

```csharp
// src/MarketData/IMarketDataProvider.cs
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace MarketData;

/// <summary>
/// A provider that streams price ticks for a set of symbols.
/// Implementations may wrap a WebSocket, REST polling, FIX, etc.
/// </summary>
public interface IMarketDataProvider
{
    /// <summary>
    /// Returns the symbols this provider can stream.
    /// </summary>
    IReadOnlyCollection<string> Symbols { get; }

    /// <summary>
    /// Starts the asynchronous price‑stream.
    /// The returned async enumerable yields new <see cref="PriceTick"/> objects as they arrive.
    /// </summary>
    IAsyncEnumerable<PriceTick> StreamAsync(CancellationToken ct = default);
}
```

### 1.3 Simple In‑Memory Cache (optional but handy)

```csharp
// src/MarketData/IPriceCache.cs
using System.Collections.Generic;

namespace MarketData;

/// <summary>
/// Stores the most‑recent price for each symbol. Thread‑safe.
/// </summary>
public interface IPriceCache
{
    void Update(PriceTick tick);
    decimal? GetLastPrice(string symbol);
    IReadOnlyDictionary<string, decimal> Snapshot(); // snapshot of all latest prices
}
```

```csharp
// src/MarketData/PriceCache.cs
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;

namespace MarketData;

public sealed class PriceCache : IPriceCache
{
    private readonly ConcurrentDictionary<string, decimal> _prices = new();

    public void Update(PriceTick tick) => _prices[tick.Symbol] = tick.Price;

    public decimal? GetLastPrice(string symbol) =>
        _prices.TryGetValue(symbol, out var price) ? price : null;

    public IReadOnlyDictionary<string, decimal> Snapshot() =>
        _prices.ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
}
```

### 1.4 Mock Provider (for testing / demo)

```csharp
// src/MarketData/MockMarketDataProvider.cs
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace MarketData;

/// <summary>
/// Generates random walk price ticks for a fixed list of symbols.
/// Useful for unit‑tests or a quick demo without external connections.
/// </summary>
public sealed class MockMarketDataProvider : IMarketDataProvider
{
    private readonly List<string> _symbols;
    private readonly Random _rnd = new();

    public MockMarketDataProvider(IEnumerable<string> symbols)
    {
        _symbols = symbols.ToList();
    }

    public IReadOnlyCollection<string> Symbols => _symbols;

    public async IAsyncEnumerable<PriceTick> StreamAsync([System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken ct = default)
    {
        // start each symbol at a random price between 20 and 200
        var last = _symbols.ToDictionary(s => s, s => (decimal)(_rnd.NextDouble() * 180 + 20));

        while (!ct.IsCancellationRequested)
        {
            foreach (var symbol in _symbols)
            {
                // simple random walk: +/- 0.5%
                var change = (decimal)(_rnd.NextDouble() - 0.5) * 0.01m;
                last[symbol] = Math.Max(1, last[symbol] * (1 + change));

                yield return new PriceTick
                {
                    Symbol = symbol,
                    Price = Math.Round(last[symbol], 4),
                    TimestampUtc = DateTime.UtcNow
                };
            }

            await Task.Delay(TimeSpan.FromSeconds(1), ct).ConfigureAwait(false);
        }
    }
}
```

