## 2️⃣ Portfolio Optimization Subsystem

### 2.1 Risk Parameters (input to the optimizer)

```csharp
// src/Optimization/RiskParameters.cs
namespace Optimization;

/// <summary>
/// Simple container for risk‑/return‑related constraints.
/// Extend as needed (e.g., sector caps, ESG scores, max turnover, etc.).
/// </summary>
public sealed record RiskParameters
{
    public decimal TargetRisk { get; init; } = 0.10m; // e.g. portfolio volatility target (10%)
    public decimal MaxWeightPerAsset { get; init; } = 0.25m; // 25% cap per ticker
    public decimal MinWeightPerAsset { get; init; } = 0.00m; // zero‑shorting by default
}
```

### 2.2 Optimizer Output

```csharp
// src/Optimization/OptimizationResult.cs
using System.Collections.Generic;

namespace Optimization;

/// <summary>
/// Result of the optimizer – a weight for each symbol (sum = 1.0).
/// </summary>
public sealed record OptimizationResult
{
    public IReadOnlyDictionary<string, decimal> TargetWeights { get; init; } = new Dictionary<string, decimal>();
    public decimal ExpectedPortfolioReturn { get; init; }
    public decimal ExpectedPortfolioRisk { get; init; } // e.g., standard deviation
}
```

### 2.3 Optimizer Interface

```csharp
// src/Optimization/IPortfolioOptimizer.cs
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using MarketData;

namespace Optimization;

/// <summary>
/// Computes the *target* allocation given the latest price snapshot and risk parameters.
/// The implementation can be mean‑variance, risk‑parity, Black‑Litterman, etc.
/// </summary>
public interface IPortfolioOptimizer
{
    Task<OptimizationResult> OptimizeAsync(
        IReadOnlyDictionary<string, decimal> latestPrices,
        RiskParameters riskParameters,
        CancellationToken ct = default);
}
```

### 2.4 Sample Mean‑Variance Optimizer (very naïve)

> **NOTE** – This is **not production‑grade**. It demonstrates the plumbing.  
> For a real system you’d plug in a proper numerical optimizer (e.g., `MathNet.Numerics`, `Accord.NET`, or a Python‑via‑gRPC service).

```csharp
// src/Optimization/MeanVarianceOptimizer.cs
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MarketData;

namespace Optimization;

/// <summary>
/// A toy mean‑variance optimizer that:
///   • assumes a diagonal covariance matrix (i.e., uncorrelated assets)
///   • uses a simple “risk‑budget” approach: weight ∝ 1 / σ
///   • respects max/min per‑asset caps
/// </summary>
public sealed class MeanVarianceOptimizer : IPortfolioOptimizer
{
    // In a real implementation you would inject a service that provides
    // historical returns & covariance matrices.
    // Here we fake volatilities with a random walk on the price series length.

    public Task<OptimizationResult> OptimizeAsync(
        IReadOnlyDictionary<string, decimal> latestPrices,
        RiskParameters riskParameters,
        CancellationToken ct = default)
    {
        // Fake volatilities: larger price → larger σ (just for demo)
        var vol = latestPrices.ToDictionary(
            kvp => kvp.Key,
            kvp => 0.02m + (kvp.Value / 1000m)); // 2% base + price‑dependent

        // Inverse‑vol weighting (risk parity style)
        var rawWeights = vol.ToDictionary(
            kvp => kvp.Key,
            kvp => 1m / kvp.Value);

        // Apply caps
        var capped = rawWeights.Select(kvp =>
        {
            var cappedWeight = Math.Clamp(kvp.Value, riskParameters.MinWeightPerAsset, riskParameters.MaxWeightPerAsset);
            return new { kvp.Key, cappedWeight };
        }).ToDictionary(x => x.Key, x => x.cappedWeight);

        // Normalise to sum = 1
        var sum = capped.Values.Sum();
        var normalised = capped.ToDictionary(kvp => kvp.Key, kvp => kvp.Value / sum);

        // Dummy expected return & risk (just for illustration)
        var expectedReturn = normalised.Sum(kvp => kvp.Value * 0.08m); // assume 8% annual return per asset
        var expectedRisk   = normalised.Sum(kvp => kvp.Value * vol[kvp.Key]); // weighted average vol

        var result = new OptimizationResult
        {
            TargetWeights = normalised,
            ExpectedPortfolioReturn = expectedReturn,
            ExpectedPortfolioRisk = expectedRisk
        };

        return Task.FromResult(result);
    }
}
```

