}
```

```csharp
// src/Execution/TradeOrder.cs
using System;

namespace Execution;

/// <summary>
/// Represents a single order to be sent to a broker.
/// </summary>
public sealed record TradeOrder
{
    public string Symbol { get; init; }          // ticker
    public OrderSide Side { get; init; }        // Buy / Sell
    public int Quantity { get; init; }          // integer shares (positive)
    public decimal LimitPrice { get; init; }    // optional limit price; 0 = market order
    public DateTime TimestampUtc { get; init; } = DateTime.UtcNow;
}
```

